"""Evaluación de acceso: rutas plausibles, supuestos y evidencia diferenciados.

No admite por mera antigüedad ni exige conocer el ejemplar material exacto.
Las admisiones inferenciales son condicionadas a las reconstrucciones declaradas.
"""
def revise(D,p,source,add,intro,translations):
    def table(name):return {x['id']:x for x in D[name]}
    def primary(key,label,url):
        sid='src_access_'+key;source(sid,label,url,'primary_text_in_translation');return sid
    acts=primary('acts_1','NABRE / USCCB — Acts 1:1–2','https://bible.usccb.org/bible/acts/1')
    luke=primary('luke_1','NABRE / USCCB — Luke 1:1–4','https://bible.usccb.org/bible/luke/1')
    john=primary('john_21','NABRE / USCCB — John 21 and editorial notes','https://bible.usccb.org/bible/john/21')
    sam=primary('samuel_31','NABRE / USCCB — 1 Samuel 31','https://bible.usccb.org/bible/1samuel/31')
    chron=primary('chronicles_10','NABRE / USCCB — 1 Chronicles 10 and notes','https://bible.usccb.org/bible/1chronicles/10')
    # These two pages are verified through Bible Gateway when USCCB blocks fetching.
    kings=primary('kings_22','NABRE — 2 Kings 22','https://www.biblegateway.com/passage/?search=2%20Kings%2022&version=NABRE')
    chron34=primary('chronicles_34','NABRE — 2 Chronicles 34','https://www.biblegateway.com/passage/?search=2%20Chronicles%2034&version=NABRE')
    common_limit=p('El acceso es una inferencia de trabajo bajo los supuestos indicados; no identifica un manuscrito, biblioteca o trayecto material.', 'Access is a working inference under the stated assumptions; it does not identify a manuscript, library or material route.')
    no_dependency=p('Se evalúa que el responsable pudo conocer el antecedente. Esto no establece por sí solo uso efectivo ni dependencia directa.', 'The assessment concerns whether the author or editor could know the antecedent. This alone does not establish actual use or direct dependence.')
    def line(kind,summary,refs,contribution):return dict(kind=kind,summary=summary,refs=refs,contribution=contribution)
    def assessment(key,fr,to,kind,label,scope,route,reason,assumptions,lines,existing=False,dependence='proposed'):
        fs='stage_'+fr;ts='stage_'+to;cid=('claim_pending_' if existing else 'claim_access_')+key
        evid=[];out_lines=[]
        for i,L in enumerate(lines,1):
            eid=f'ev_access_review_{key}_{i}';basis=f'basis_access_review_{key}_{i}';evid.append(eid)
            D['evidence'].append(dict(id=eid,kind=L['kind'],basis_id=basis,summary=p(*L['summary']),citations=[dict(source_id=s,locator=p(*loc)) for s,loc in L['refs']],supports_claim_ids=[cid],limitations=[common_limit]))
            out_lines.append(dict(basis_id=basis,evidence_ids=[eid],contribution=p(*L['contribution'])))
        scope=p(*scope);route=p(*route);reason=p(*reason);assumptions=[p(*a) for a in assumptions]
        limits=[common_limit,*assumptions,no_dependency]
        if existing:
            claim=table('claims')[cid]
            old='ev_pending_'+key;D['evidence'][:]=[e for e in D['evidence'] if e['id']!=old]
        else:
            claim=dict(id=cid,subject_id=ts);D['claims'].append(claim)
            table('stages')[ts]['claim_ids'].append(cid)
            for sc in D['scenarios']:sc['selected_claim_ids'].append(cid)
        claim.update(predicate='presumed_access',value=scope,evidence_ids=evid,status='working_hypothesis',certainty_rationale=reason,counterarguments=limits)
        fid='form_access_review_'+key
        source_stage=table('stages')[fs]
        D['forms'].append(dict(id=fid,stage_id=fs,language=source_stage['languages'][0] if len(source_stage['languages'])==1 else None,scope=scope,existence_date_ids=[],availability_claim_ids=[cid],notes=p('Se delimita el antecedente pertinente; no se supone que coincida con toda la edición canónica actual.', 'The pertinent antecedent is delimited; it is not assumed to match the whole present canonical edition.')))
        for sc in D['scenarios']:
            if existing:e=next(e for e in D['access_evaluations'] if e['id']=='candidate_'+key+('_alt' if sc['id']=='scenario_alternatives' else ''))
            else:
                e=dict(id='access_'+key+('_alt' if sc['id']=='scenario_alternatives' else ''),from_stage_id=fs,to_stage_id=ts,scenario_id=sc['id']);D['access_evaluations'].append(e)
            attr=next(a for a in sc['selected_attribution_ids'] if table('attributions')[a]['stage_id']==ts)
            e.update(source_form_id=fid,recipient_attribution_id=attr,status='admitida',checks={k:'supported' for k in ['prior_existence','contextual_availability','linguistic_access','access_before_reception_during_activity']},check_evidence={k:list(evid) for k in ['prior_existence','contextual_availability','linguistic_access','access_before_reception_during_activity']},evidence_lines=out_lines,
                independence_rationale=p('Se distinguen identificación o continuidad específica y condiciones de transmisión. Pueden compartir una reconstrucción editorial: no se presentan como testimonios estadísticamente independientes ni se cuentan las síntesis repetidas como nuevas pruebas.', 'Specific identification or continuity is distinguished from transmission conditions. They may share an editorial reconstruction: they are not presented as statistically independent witnesses, and repeated syntheses are not counted as new evidence.'),route=route,scope=scope,
                access_time_description=p('El antecedente pertinente precede al trabajo receptor bajo los supuestos declarados; el acceso se sitúa durante esa actividad, sin inventar fechas de vida ni el día de consulta.', 'The pertinent antecedent precedes receiving work under the stated assumptions; access falls within that activity without inventing life dates or a day of consultation.'),justification=reason,limitations=limits,
                dependence=dict(status=dependence,evidence_ids=[] if dependence=='not_evaluated' else evid,notes=no_dependency),access_basis=dict(kind=kind,label=p(*label),reason=reason,assumptions=assumptions,route_certainty='inferred'))
    for key,target,n in [('mark_matt','mat',47),('mark_luke','luk',49)]:
        assessment(key,'mrk',target,'literary_transmission',('Fuente griega','Greek source'),
            ('Forma griega de Marcos pertinente para las secuencias sinópticas, hasta el cierre de 16:8; no incluye automáticamente los finales añadidos.', 'A Greek form of Mark pertinent to synoptic sequences through the ending at 16:8; added endings are not automatically included.'),
            ('Circulación y consulta de un relato griego anterior en el entorno redactor del evangelio receptor, inferidas de las secuencias y reescrituras publicadas.', 'Circulation and consultation of an earlier Greek narrative in the receiving Gospel’s editorial setting, inferred from published sequences and rewritings.'),
            ('Bajo la prioridad de Marcos, la lengua común, el orden narrativo y las reelaboraciones específicas hacen plausible que el redactor pudiera consultar ese relato anterior. No se exige una cita explícita ni conocer su ejemplar exacto.', 'Under Markan priority, shared language, narrative order and specific rewritings make the earlier account plausibly available to the editor. Neither an explicit quotation nor an identified exemplar is required.'),
            [('Se adopta la prioridad de Marcos y su función de fuente propuesta; otras soluciones sinópticas requieren una evaluación diferente.', 'Markan priority and the proposed source role are adopted; other synoptic solutions require a different assessment.')],
            [line('published_textual_comparison',('Las coincidencias de secuencia y redacción y las modificaciones del receptor apuntan a un antecedente escrito identificable, según el análisis sinóptico publicado.', 'Published synoptic analysis identifies sequence and wording agreements and receiving modifications that point to an identifiable written antecedent.'),[('src_synoptic',('Prioridad de Marcos: orden, redacción y dificultades corregidas.','Markan priority: order, wording and corrected difficulties.'))],('Indicio específico de acceso a una narración escrita, más allá de un tema compartido.','Specific indication of access to a written narrative, beyond a shared theme.')),
             line('historiographical_argument',('Las dataciones y lenguas propuestas sitúan Marcos antes de la actividad receptora; la introducción identifica ese relato entre las fuentes probables.', 'Proposed dates and languages place Mark before receiving activity; the introduction identifies that narrative among probable sources.'),[(intro[48],('Introducción: fecha y lengua del relato.','Introduction: narrative date and language.')),(intro[n],('Introducción: fuentes y composición.','Introduction: sources and composition.')),*([(luke,('Lucas 1:1–4: relatos anteriores y tarea de composición.','Luke 1:1–4: prior accounts and composition.'))] if n==49 else [])],('Condiciones cronológicas, lingüísticas y editoriales de disponibilidad.','Chronological, linguistic and editorial conditions of availability.'))],existing=True)
    assessment('luke_acts','luk','act','editorial_continuity',('Continuidad','Continuity'),
        ('Una forma del relato anterior dedicado a Teófilo, identificada con Lucas; no se fija cada variante de su edición.', 'A form of the earlier account dedicated to Theophilus, identified with Luke; not every edition variant is fixed.'),
        ('Continuidad del proyecto literario: el responsable del segundo volumen podía conocer el relato anterior que declara haber compuesto.', 'Continuity of the literary project: the second volume’s author could know the previous account they declare having composed.'),
        ('La remisión a un primer relato y la identificación del proyecto Lucas–Hechos respaldan acceso al antecedente durante la composición de Hechos, sin exigir una cita de sus versículos.', 'Reference to a first account and identification of the Luke–Acts project support access to the antecedent during Acts’ composition without requiring verse quotation.'),
        [('Se acepta la identificación del primer relato con Lucas y la continuidad de autoría o de responsabilidad editorial de los dos volúmenes.', 'The first account is identified with Luke and continuity of authorship or editorial responsibility across the volumes is accepted.')],
        [line('ancient_testimony',('Hechos 1:1–2 remite al relato anterior del mismo narrador y destinatario.', 'Acts 1:1–2 refers to the same narrator’s prior account and addressee.'),[(acts,('Hechos 1:1–2.','Acts 1:1–2.'))],('Testimonio interno específico de conocimiento previo.','Specific internal testimony of prior knowledge.')),
         line('historiographical_argument',('Las introducciones interpretan Lucas y Hechos como dos volúmenes de un proyecto en griego; los prólogos permiten precisar el antecedente.', 'The introductions interpret Luke and Acts as two volumes of a Greek project; the prologues delimit the antecedent.'),[(intro[49],('Introducción: obra de dos volúmenes.','Introduction: two-volume work.')),(intro[51],('Introducción: continuidad literaria.','Introduction: literary continuity.')),(luke,('Lucas 1:1–4.','Luke 1:1–4.'))],('Identificación del antecedente y vía de continuidad editorial.','Identification of the antecedent and editorial-continuity route.'))],existing=True)
    for key,fr,to,a,b,source_locator,target_locator in [
        ('sam_chron','1sa','1ch',sam,chron,('1 Samuel 31.','1 Samuel 31.'),('1 Crónicas 10 y notas.','1 Chronicles 10 and notes.')),
        ('kings_chron','2ki','2ch',kings,chron34,('2 Reyes 22.','2 Kings 22.'),('2 Crónicas 34:8–28 y notas.','2 Chronicles 34:8–28 and notes.'))]:
        assessment(key,fr,to,'literary_transmission',('Uso de fuentes','Source access'),
            ('Antecedentes narrativos hebreos de Samuel–Reyes, delimitados por los paralelos con Crónicas; no la totalidad de cada libro actual.', 'Hebrew Samuel–Kings narrative antecedents delimited by Chronicles parallels, not the entirety of each present book.'),
            ('Consulta o mediación de materiales históricos conservados por escribas en el entorno del Cronista. Se infiere disponibilidad textual; no se identifica un archivo del Templo.', 'Consultation or mediation of historical materials preserved by scribes in the Chronicler’s setting. Textual availability is inferred; no Temple archive is identified.'),
            ('Los paralelos narrativos concretos y la reconstrucción del trabajo del Cronista hacen plausible acceso a antecedentes de Samuel–Reyes antes de reescribirlos. La inferencia se limita a esos materiales.', 'Concrete narrative parallels and reconstruction of the Chronicler’s work make Samuel–Kings antecedents plausibly accessible before rewriting. The inference is limited to those materials.'),
            [('Se adopta la reconstrucción del Cronista como recopilador posterior que tuvo disponibles antecedentes hebreos de Samuel–Reyes; sus ediciones completas permanecen abiertas.', 'The Chronicler is reconstructed as a later compiler with Hebrew Samuel–Kings antecedents available; their complete editions remain open.')],
            [line('published_textual_comparison',('La secuencia narrativa y su reelaboración se identifican en los pasajes paralelos y sus referencias editoriales.', 'Narrative sequence and reworking are identified in parallel passages and editorial references.'),[(a,source_locator),(b,target_locator)],('Correspondencia específica y transformación editorial del antecedente.','Specific correspondence and editorial transformation of the antecedent.')),
             line('historiographical_argument',('La introducción sitúa el trabajo del Cronista a finales del siglo V a. C. e identifica Samuel y Reyes entre sus fuentes históricas.', 'The introduction places the Chronicler’s work in the late fifth century BCE and identifies Samuel and Kings among historical sources.'),[(intro[13],('Introducción: responsable, situación y fuentes.','Introduction: author, setting and sources.'))],('Contexto de preservación y trabajo con fuentes en hebreo.','Setting of preservation and work with Hebrew sources.'))],existing=True)
    assessment('john_epilogue','jhn_main','jhn_epilogue','editorial_continuity',('Redacción','Editing'),
        ('Forma antecedente del evangelio con cierre en Juan 20:30–31, disponible para la elaboración del capítulo 21.', 'An antecedent Gospel form ending at John 20:30–31, available for producing chapter 21.'),
        ('Acceso dentro de la continuidad editorial que añade un epílogo al relato existente; responsable y lugar exactos desconocidos.', 'Access within editorial continuity adding an epilogue to an existing account; the exact editor and place are unknown.'),
        ('Si el capítulo 21 es un epílogo añadido, su responsable pudo conocer el cuerpo al que lo incorporó. El cierre anterior y la referencia al testimonio escrito respaldan esta reconstrucción.', 'If chapter 21 is an added epilogue, its editor could know the body to which it was attached. The prior ending and reference to written testimony support this reconstruction.'),
        [('Se adopta la hipótesis editorial de un epílogo posterior; no se identifica al redactor con un apóstol ni se fecha su vida.', 'The hypothesis of a later editorial epilogue is adopted; the editor is not identified with an apostle and no life dates are assigned.')],
        [line('published_textual_comparison',('El cierre en 20:30–31 y la continuación de 21 permiten distinguir una intervención posterior bajo esta hipótesis.', 'The ending at 20:30–31 and continuation in 21 distinguish a later intervention under this hypothesis.'),[(intro[50],('Introducción: cierre anterior y epílogo añadido.','Introduction: prior ending and added epilogue.'))],('Estratificación editorial específica.','Specific editorial stratification.')),
         line('ancient_testimony',('Juan 21:24–25 vincula el epílogo con el testimonio escrito y el libro recibido; no es una cita formal del capítulo 20.', 'John 21:24–25 links the epilogue to written testimony and the received book; it is not a formal quotation of chapter 20.'),[(john,('Juan 21:24–25 y notas.','John 21:24–25 and notes.'))],('Continuidad con el testimonio textual al que se añade el epílogo.','Continuity with the textual testimony receiving the epilogue.'))],existing=True)
    for key,fr,to,n1,n2 in [('prior_1th_1co','1th','1co',59,53),('prior_1th_rom','1th','rom',59,52),('prior_1co_2co','1co','2co',53,54)]:
        a=table('works')[table('stages')['stage_'+fr]['work_id']]['label'];b=table('works')[table('stages')['stage_'+to]['work_id']]['label']
        assessment(key,fr,to,'common_authorship',('Autor común','Same author'),
            ('Contenido de la carta paulina anterior durante la actividad de Pablo, sin presuponer conocimiento de toda adición editorial posterior.', 'Content of the earlier Pauline letter during Paul’s activity, without presuming knowledge of every later editorial addition.'),
            ('Conocimiento por composición propia y continuidad de la actividad epistolar de Pablo; puede mantenerse en memoria o mediante colaboradores. No se afirma conservación de un autógrafo.', 'Knowledge through own composition and continuity of Paul’s letter-writing activity; memory or collaborators may preserve it. Retention of an autograph is not asserted.'),
            (f'Bajo la atribución de ambas cartas a Pablo y la cronología seleccionada, {a} ya había sido compuesta antes de {b}. El mismo responsable podía conocer su texto anterior; no hace falta que lo cite ni se afirma que lo reutilizara.', f'Under attribution of both letters to Paul and the selected chronology, the earlier letter was composed before the receiving one. The same author could know their previous text; no quotation is required and reuse is not asserted.'),
            [('Se aplica a los contenidos atribuidos a Pablo y al orden temporal documentado, no a capas añadidas por recopiladores posteriores.', 'This applies to content attributed to Paul and the documented temporal order, not layers added by later compilers.')],
            [line('historiographical_argument',('Las introducciones atribuyen los contenidos de ambas cartas al mismo Pablo; no se deduce identidad únicamente de una etiqueta de autor.', 'The introductions attribute both letters’ contents to the same Paul; identity is not inferred merely from an author label.'),[(intro[n1],('Introducción: atribución paulina.','Introduction: Pauline authorship.')),(intro[n2],('Introducción: atribución y responsabilidad de los contenidos.','Introduction: authorship and responsibility for contents.'))],('Vía específica: conocimiento por composición propia.','Specific route: knowledge through own composition.')),
             line('historiographical_argument',('Las dataciones y la continuidad de la actividad epistolar situadas por las introducciones respaldan existencia previa durante la actividad del receptor.', 'Dating and continuity of letter-writing activity in the introductions support prior existence during receiving activity.'),[(intro[n1],('Introducción: fecha y ocasión de la carta anterior.','Introduction: date and occasion of the earlier letter.')),(intro[n2],('Introducción: ocasión y fecha de composición receptora.','Introduction: occasion and date of receiving composition.'))],('Cronología y continuidad de actividad, distinguidas de identidad y dependencia.','Chronology and continuity of activity, distinguished from identity and dependence.'))],dependence='not_evaluated')
    # Access by the compiler must not be imputed to every earlier story/vision author.
    add(34,key='assembly',kind='collection',label=('Daniel · reunión de relatos y visiones','Daniel · assembly of stories and visions'),dates=(-167,-164),languages=['he','arc'],actor=(p('Redactor o grupo recopilador de Daniel, hipótesis','Daniel editor or compiling group, hypothesis'),'unknown',p('Responsable de la reunión hipotética; identidad y fechas de vida desconocidas.','Editor of the hypothetical assembly; identity and life dates are unknown.')),scope=('Reunión propuesta de antecedentes de Daniel 1–6 y 7–12 en una colección hebrea-aramea; excluye las adiciones griegas.','Proposed assembly of Daniel 1–6 and 7–12 antecedents in a Hebrew-Aramaic collection; Greek additions are excluded.'),date_notes=('167–164 a. C. es el marco de composición de la obra propuesto en la síntesis, aplicado como contexto de reunión. El momento exacto de cada incorporación sigue desconocido.','167–164 BCE is the synthesis’s proposed composition setting, used as assembly context. The exact time of each incorporation remains unknown.'))
    stage=table('stages')['stage_dan_assembly']
    for sc in D['scenarios']:
        for k,vals in [('active_stage_ids',[stage['id']]),('selected_attribution_ids',stage['attribution_ids']),('selected_date_ids',stage['date_ids']),('selected_claim_ids',stage['claim_ids'])]:sc[k].extend(vals)
    for key,fr in [('dan_tales_assembly','dan_tales'),('dan_visions_assembly','dan_visions')]:
        assessment(key,fr,'dan_assembly','collection',('Recopilación','Assembly'),
            ('Antecedentes de los relatos o visiones incorporados a la colección hebrea-aramea de Daniel, no toda su edición católica posterior.', 'Story or vision antecedents incorporated into the Hebrew-Aramaic Daniel collection, not its whole later Catholic edition.'),
            ('Disponibilidad de los materiales para el responsable que los reúne y organiza, dentro del proceso de recopilación; no se atribuye ese acceso a cada autor anterior.', 'Materials available to the editor assembling and organizing them within compilation; this access is not attributed to every earlier author.'),
            ('La reunión de materiales distinguibles hace plausible su acceso por el recopilador antes de componer la colección. El vínculo termina en la etapa de reunión y conserva separados los autores de los relatos y de las visiones.', 'Assembly of distinguishable materials makes them plausibly accessible to the compiler before composing the collection. The relationship ends at the assembly stage, keeping story and vision authors separate.'),
            [('Se adopta una reunión de antecedentes ya disponibles, incluidos borradores, no una fecha anterior demostrada para cada capítulo ni una biografía de su recopilador.', 'Assembly of already available antecedents, including drafts, is adopted; no proven earlier date for every chapter or compiler biography is supplied.')],
            [line('published_textual_comparison',('La síntesis distingue relatos y visiones dentro de una obra de contenido y lenguas diversos.', 'The synthesis distinguishes stories and visions within a work of varied content and languages.'),[(intro[34],('Introducción: estructura y diversidad de materiales.','Introduction: structure and diversity of materials.'))],('Materiales específicos que confluyen en una unidad receptora distinta.','Specific materials converging into a distinct receiving unit.')),
             line('historiographical_argument',('El contexto macabeo propuesto para la obra y su organización permiten situar la actividad recopiladora sin confundirla con el escenario babilónico narrado.', 'The proposed Maccabean setting and organization locate compiling activity without conflating it with the narrated Babylonian setting.'),[(intro[34],('Introducción: composición en 167–164 a. C.','Introduction: composition in 167–164 BCE.'))],('Contexto lingüístico y editorial de disponibilidad durante la recopilación.','Linguistic and editorial setting of availability during compilation.'))],dependence='proposed')
    for e in D['access_evaluations']:
        if 'access_basis' in e:continue
        if e['dependence']['status']=='translation_attested':
            e['access_basis']=dict(kind='translation',label=p('Traducción','Translation'),reason=p('El traductor declara trabajar con el antecedente de su abuelo; el testimonio y las correspondencias textuales respaldan acceso durante esa tarea.', 'The translator declares working with their grandfather’s antecedent; testimony and textual correspondences support access during that task.'),assumptions=[p('La forma hebrea exacta no está identificada con un manuscrito conservado.', 'The exact Hebrew form is not identified with a surviving manuscript.')],route_certainty='attested')
        elif e['status']=='admitida':
            e['access_basis']=dict(kind='textual_reception',label=p('Recepción','Reception'),reason=p('La incorporación identificable de contenido antecedente respalda que el responsable pudo conocerlo antes de escribir la parte receptora. La cita es evidencia de acceso al fragmento; no define la regla del grafo.', 'Identifiable incorporation of antecedent content supports the author’s ability to know it before writing the receiving part. Quotation is evidence of access to the excerpt; it does not define the graph’s rule.'),assumptions=[p('El acceso pudo ser directo o mediado; no se acredita el libro íntegro ni un canal material específico.', 'Access may be direct or mediated; the whole book and a specific material channel are not established.')],route_certainty='unknown')
        else:
            e['access_basis']=dict(kind='unresolved',label=p('Por evaluar','To assess'),reason=p('La hipótesis tiene respaldo publicado, pero esta evaluación aún debe precisar y contrastar la disponibilidad de una forma pertinente antes de la composición receptora. No se exige identificar el ejemplar exacto.', 'The hypothesis has published support, but this assessment still needs to delimit and test availability of a pertinent form before receiving composition. Identifying the exact exemplar is not required.'),assumptions=[p('Una tradición común o una prioridad alternativa pueden cambiar la dirección y el alcance propuestos.', 'A common tradition or alternative priority can change the proposed direction and scope.')],route_certainty='unknown')
    # Keep canonical reading order, with assembly immediately after Daniel's visions.
    order={s['id']:i for i,s in enumerate(D['stages'])};order['stage_dan_assembly']=order['stage_dan_visions']+.5
    works=table('works');stages=table('stages')
    D['stages'].sort(key=lambda s:(works[s['work_id']]['canonical_order'],order[s['id']]))
    for sc in D['scenarios']:
        sc['active_stage_ids'].sort(key=lambda sid:(works[stages[sid]['work_id']]['canonical_order'],order[sid]))
        sc['notes']=p(sc['notes']+' Las admisiones de acceso por transmisión y redacción se condicionan a los supuestos explícitos de cada evaluación; no se exige una cita bíblica.',translations.get(sc['notes'],sc['notes'])+' Access admissions from transmission and editing are conditional on each assessment’s explicit assumptions; a biblical quotation is not required.')
    D['schema_version']='0.2'
